// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // the test contract is C's owner and the withdrawal recipient; it must accept ETH
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        // fund the contract through its payable fallback so depositsCount increments too
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);
        require(address(c).balance == amount);

        // owner (this test contract) drains everything via withdrawAll
        vm.prank(address(this));
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // rule: after a successful owner withdrawAll, the contract balance is exactly zero
        assertTrue(ok && address(c).balance == 0);
    }
}
